import sys; sys.path.insert(0,'/tmp/dr_k73_fit')
import fit
p={'C1':(0.0920516,540.33),'C2':(0.0344613,628.42),'C3':(0.0701719,665.063),'C4':(0.0959863,750.71),'C5':(0.0920516,2762.78),'C6':(0.0312331,339.453),'C7':(0.0701719,2914.4)}
ex=set(fit.EXCLUDED)
for c in p:
    rows=[(s,fit.CONV[u](v)*fit.DILUTION_FACTOR.get(c,1.0),sid) for sid,cc,s,v,u in fit.WELLS if cc==c and sid not in ex]
    rows.sort()
    V,K=p[c]
    rmax=max(rows)
    print(c, 'n',len(rows),'top S', rmax[0], 'obs %.4f' % rmax[1], 'pred %.4f' % (V*rmax[0]/(K+rmax[0])), 'max resid %.4f' % max(abs(v-V*s/(K+s)) for s,v,_ in rows))
